import style from "./Login.module.css"
import React from "react";
import { Navigate } from "react-router-dom";
import { useForm } from "react-hook-form";

const LoginForm = (props) => {
    const { register, handleSubmit, formState: { errors, isValid } } = useForm({
        mode: 'all',
        defaultValues: { rememberMe: false }
    });

    // useState для отслеживания состояния отправки формы
    const [isSubmitting, setIsSubmitting] = React.useState(false);

    const onSubmit = async (data) => {
        setIsSubmitting(true); // Начало отправки
        try {
            await props.userLogin(data);
        } catch (error) {
            console.error('Login error:', error);
        } finally {
            setIsSubmitting(false); // Конец отправки
        }
    }

    return (
        <form onSubmit={handleSubmit(onSubmit)}>
            <div className={`${style.loginInput} ${errors?.email?.message ? style.loginInput__error : ''}`}>
                <label>Email</label>
                <input
                    {...register('email', {
                        required: 'Поле обязательно к заполнению',
                        minLength: {
                            value: 5,
                            message: 'Не меньше 5 символов'
                        }
                    })}
                    placeholder="Email"
                    disabled={isSubmitting} // Блокировка во время отправки
                />
                <div className={style.errorMessage}>
                    {errors?.email && <p>{errors?.email?.message || 'Error'}</p>}
                </div>
            </div>
            
            <div className={`${style.loginInput} ${errors?.password?.message ? style.loginInput__error : ''}`}>
                <label>Password</label>
                <input
                    {...register('password', {
                        required: 'Поле обязательно к заполнению',
                    })}
                    type={'password'}
                    placeholder="Password"
                    disabled={isSubmitting} // Блокировка во время отправки
                />
                <div className={style.errorMessage}>
                    {errors?.password && <p>{errors?.password?.message || 'Error'}</p>}
                </div>
            </div>
            
            <div className={style.submitWrapp}>
                <div className={style.loginCheck}>
                    <label>
                        <input
                            {...register('rememberMe')}
                            type={"checkbox"}
                            disabled={isSubmitting} // Блокировка во время отправки
                        />
                        <span></span>
                        Remember me
                    </label>
                </div>
                <div className={style.loginSubmit}>
                    <input 
                        type="submit" 
                        value={isSubmitting ? 'Logging in...' : 'Login'} // Меняем текст при отправке
                        disabled={!isValid || isSubmitting} // Блокировка если форма не валидна или отправляется
                    />
                </div>
            </div>
            
            <div className={style.errorMessage}>
                {props.errorMessage ? <p>{props.errorMessage}</p> : ''}
            </div>
            
            {props.captchaURL ?
                <div className={style.captchaField}>
                    <img src={props.captchaURL} alt="captcha" />
                    <input
                        {...register('captchaValue', {
                            required: 'Поле обязательно к заполнению'
                        })}
                        type="text"
                        placeholder="Enter captcha"
                        disabled={isSubmitting} // Блокировка во время отправки
                    />
                    <div className={style.errorMessage}>
                        {errors?.captchaValue && <p>{errors?.captchaValue?.message || 'Error'}</p>}
                    </div>
                </div>
                : ''
            }
        </form>
    )
}

// Отдельный компонент для тестовых данных с useState
const TestData = () => {
    // useState для управления видимостью тестовых данных
    const [isVisible, setIsVisible] = React.useState(true);

    if (!isVisible) return null;

    return (
        <div className={style.testData}>
            <button 
                onClick={() => setIsVisible(false)}
                className={style.closeButton}
            >
                ×
            </button>
            <h3>Тестовые данные.</h3>
            <p>Email: <span>free@samuraijs.com</span></p>
            <p>Password: <span>free</span></p>
        </div>
    )
}

export default function Login(props) {
    if (props.isAuth) {
        return <Navigate to={'/profile'} />
    }
    
    return (
        <div className={style.loginWrapp}>
            <h1>Login</h1>
            <LoginForm {...props} />
            <TestData />
        </div>
    )
}